import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// issue #12: the customer's discount must be applied exactly once.
const lines = (count, price) =>
  Array.from({ length: count }, () => ({ price, qty: 1 }));

test('customer discount is applied once (under 10 lines)', () => {
  // 1,000 with a 10% customer discount -> 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount (10 lines)', () => {
  // 10,000 -> 9,000 (10% customer) -> 8,550 (5% bulk)
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('no bulk discount under 10 lines, customer discount still once (9 lines)', () => {
  // 9,000 -> 8,100 (10% customer), no bulk discount
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('totals with a discount rate of 0 are unchanged', () => {
  // Values recorded from the implementation before the issue #12 fix.
  assert.equal(total(lines(9, 1000), 0), 9000);
  assert.equal(total(lines(10, 1000), 0), 9500); // 5% bulk only
  assert.equal(total(lines(10, 1000)), 9500); // rate omitted
  assert.equal(total(lines(10, 333), 0), 3164); // 3,163.5 rounds up
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
